 * This record, or `RecordError` `invalidRecord` when its canonical bytes pass {@link recordLimit} in UTF-8. Every
 * store's `add` asks it of each record of a batch before it writes any.
 */
storable(): SharedRecord {
	if (Buffer.byteLength(this.bytes) > recordLimit) throw invalid(`a record is at most ${recordLimit} bytes`);

abridged(note: string): Finding {
	const { explanation } = this.properties;
	const what =
		Buffer.byteLength(explanation.what) < Buffer.byteLength(this.message.text)
			? explanation.what
			: this.message.text;
	return Finding.parse({
		...this.toJSON(),
		properties: { ...this.properties, explanation: { ...explanation, what, whyHere: note } },
	});
}

function bytes(value: unknown): number {
	return Buffer.byteLength(canonicalJson(value));
}

const tree = (scripts: Record<string, string>) =>
